#include <bits/stdc++.h>

using namespace std;

#define int long long
const int LIM = 2e5;

bool is_increasing(const vector<int> &vec) {
  for (int i = 0; i < vec.size() - 1; i++) {
    if (vec[i] >= vec[i + 1])
      return false;
  }
  return true;
}

bool is_decreasing(const vector<int> &vec) {
  for (int i = 0; i < vec.size() - 1; i++) {
    if (vec[i] <= vec[i + 1])
      return false;
  }
  return true;
}

vector<int> rollback(const vector<int> &vec) {
  vector<int> ans(vec.size());
  ans[0] = vec[0];
  for (int i = 1; i < vec.size(); i++)
    ans[i] = vec[i] - vec[i - 1];
  return ans;
}

signed main() {
  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (int &i : a)
    cin >> i;
  for (int &i : b)
    cin >> i;
  vector<int> a_rev = a;
  reverse(a_rev.begin(), a_rev.end());

  if (n == 1) {
    if (a == b)
      cout << "SMALL" << '\n' << 0 << '\n';
    else
      cout << "IMPOSSIBLE" << '\n';
    return 0;
  }

  int sum_a = accumulate(a.begin(), a.end(), 0LL);
  int sum_b = accumulate(b.begin(), b.end(), 0LL);
  int rollback_cnt = 0;

  if (n == 2) {
    vector<int> ans; // -1 = R, X = PPP..PP (x times)
    int move_cnt = 0, roll_cnt = 0;  // both types

    bool rev = a[0] > a[1];
    if (rev)
      swap(a[0], a[1]);

    if (b[0] > b[1]) {
      swap(b[0], b[1]);
      ans.push_back(-1);
      move_cnt++;
    }
    while (true) {
      if (sum_a > sum_b) {
        cout << "IMPOSSIBLE" << '\n';
        return 0;
      }

      if (sum_a == sum_b) {
        if (a != b) {
          cout << "IMPOSSIBLE" << '\n';
          return 0;
        }

        if (rev) {
          ans.push_back(-1);
          move_cnt++;
        }

        if (rollback_cnt > LIM) {
          cout << "BIG" << '\n' << rollback_cnt << '\n';
          return 0;
        } else {
          cout << "SMALL" << '\n' << move_cnt << '\n';
          reverse(ans.begin(), ans.end());
          for (auto i : ans) {
            if (i == -1)
              cout << "R";
            else {
              for (int _ = 0; _ < i; _++)
                cout << "P";
            }
          }
          cout << '\n';
          return 0;
        }
      }

      if (a[0] == b[0]) {
        if ((b[1] - a[1]) % b[0] == 0) {
          roll_cnt = (b[1] - a[1]) / b[0];
          ans.push_back(roll_cnt);
          move_cnt += roll_cnt, rollback_cnt += roll_cnt;
          b = a;
          sum_b = b[0] + b[1];
        } else {
          cout << "IMPOSSIBLE" << '\n';
          return 0;
        }
      } else {
        roll_cnt = b[1] / b[0];
        ans.push_back(roll_cnt);
        move_cnt += roll_cnt, rollback_cnt += roll_cnt;

        ans.push_back(-1);
        move_cnt++;
        swap(b[0], b[1]);
        b[0] %= b[1];
        sum_b = b[0] + b[1];
      }
    }
  }

  string ans;

  while (true) {
    if (sum_a == sum_b) {
      if (a_rev == b) {
        ans.push_back('R');
        reverse(b.begin(), b.end());
      }
      if (a == b) {
        reverse(ans.begin(), ans.end());
        if (rollback_cnt > LIM)
          cout << "BIG" << '\n' << rollback_cnt << '\n';
        else
          cout << "SMALL" << '\n' << ans.size() << '\n' << ans << '\n';
      } else
        cout << "IMPOSSIBLE" << '\n';
      return 0;
    } else if (is_increasing(b)) {
      b = rollback(b);
      sum_b = accumulate(b.begin(), b.end(), 0LL);
      ans += 'P';
      rollback_cnt++;
    } else if (is_decreasing(b)) {
      reverse(b.begin(), b.end());
      ans += 'R';
    } else {
      cout << "IMPOSSIBLE" << '\n';
      return 0;
    }
  }
}

#include <bits/stdc++.h>

using namespace std;
#define int long long

signed main() {
  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; ++i) cin >> a[i];
  for (int i = 0; i < n; ++i) cin >> b[i];
  if (n == 1) {
    if (a[0] == b[0]) cout << "SMALL\n" << 0;
    else cout << "IMPOSSIBLE";
    return 0;
  }
  if (n == 2) {
    vector<pair<int, bool>> res;
    int kol = 0;
    while (true) {
      if (b[0] == 0 || b[1] == 0) {
        cout << "IMPOSSIBLE";
        return 0;
      }
      if (a == b) break;
      if (a[0] == b[1] && a[1] == b[0]) {
        res.emplace_back(1, false);
        break;
      }
      if (b[0] == b[1]) {
        cout << "IMPOSSIBLE";
        return 0;
      }
      if (b[0] > b[1]) {
        res.emplace_back(1, false);
        swap(b[0], b[1]);
      }
      if (a[0] == b[0] && a[1] < b[1] && a[1] % b[0] == b[1] % b[0]) {
        res.emplace_back((b[1] - a[1]) / b[0], true);
        kol += res.back().first;
        break;
      }
      if (a[1] == b[0] && a[0] < b[1] && a[0] % b[0] == b[1] % b[0]) {
        res.emplace_back((b[1] - a[0]) / b[0], true);
        kol += res.back().first;
        res.emplace_back(1, false);
        break;
      }
      kol += b[1] / b[0];
      res.emplace_back(b[1] / b[0], true);
      b[1] %= b[0];
    }
    if (kol > 2e5) {
      cout << "BIG\n";
      cout << kol;
    } else {
      cout << "SMALL\n";
      int flex = 0;
      for (auto i : res) flex += i.first;
      cout << flex << "\n";
      for (int i = res.size() - 1; i >= 0; --i) {
        for (int j = 0; j < res[i].first; ++j) {
          if (res[i].second) cout << "P";
          else cout << "R";
        }
      }
    }
    return 0;
  }
  vector<bool> ans;
  int kol = 0;
  while (true) {
    if (a == b) break;
    reverse(b.begin(), b.end());
    if (a == b) {
      ans.push_back(false);
      break;
    }
    reverse(b.begin(), b.end());
    bool vozr = false, ub = false, r = false;
    for (int i = 1; i < n; ++i) {
      if (b[i] > b[i - 1]) vozr = true;
      else if (b[i] < b[i - 1]) ub = true;
      else r = true;
    }
    if (r || (vozr && ub)) {
      cout << "IMPOSSIBLE";
      return 0;
    }
    vector<int> c(n);
    if (ub) {
      ans.push_back(false);
      reverse(b.begin(), b.end());
    }
    c[0] = b[0];
    for (int i = 1; i < n; ++i) {
      c[i] = b[i] - b[i - 1];
    }
    ans.push_back(true);
    b = c;
    ++kol;
  }
  if (kol > 2e5) {
    cout << "BIG\n" << kol;
  } else {
    cout << "SMALL\n" << ans.size() << "\n";
    for (int i = ans.size() - 1; i >= 0; --i) {
      if (ans[i]) cout << "P";
      else cout << "R";
    }
  }
}
